function openPanel(panel) {
  const controller = new AbortController();
  const { signal } = controller;
  const close = () => {
    panel.hidden = true;
    controller.abort(); // removes both listeners
  };
  const onKey = (event) => {
    if (event.key === 'Escape') close();
  };
  const onClick = (event) => {
    if (event.target.closest('[data-close]')) close();
  };

  panel.hidden = false;
  document.addEventListener('keydown', onKey, { signal });
  panel.addEventListener('click', onClick, { signal });
}

const status = document.querySelector('#status');

async function showGitHubUser(username) {
  status.textContent = 'Loading…';
  try {
    const response = await fetch(`https://api.github.com/users/${username}`);
    if (!response.ok) throw new Error(`GitHub answered ${response.status}`);
    const user = await response.json();
    status.textContent = `${user.name} has ${user.public_repos} public repositories.`;
  } catch (error) {
    status.textContent = `Could not load ${username}. Try again later.`;
    console.error(error);
  }
}

showGitHubUser('octocat');

async function loadDashboard() {
  // Independent: start both requests, then wait for both.
  const [user, notifications] = await Promise.all([
    getJson('/api/me'),
    getJson('/api/notifications'),
  ]);

  // Dependent: this request needs user.teamId, so it has to wait.
  const team = await getJson(`/api/teams/${user.teamId}`);

  return { user, notifications, team };
}

let controller;

async function search(query) {
  controller?.abort(); // cancel the previous search if it is still running
  controller = new AbortController();
  try {
    const url = `/api/search?q=${encodeURIComponent(query)}`;
    const results = await getJson(url, { signal: controller.signal });
    showResults(results);
  } catch (error) {
    if (error.name === 'AbortError') return; // a newer search replaced this one
    showError(error);
  }
}

